from rules import amount


def solve(data):
    events = data['events']
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    # Apply the cutoff before resolving duplicate IDs.
    for position, event in enumerate(events):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)

        revision = event.get('revision', 0)
        previous = winners.get(key)
        if previous is None or revision >= previous[0]:
            winners[key] = (revision, position, event)

    # Opening-only and zero-valued opening balances must remain present.
    balances = dict(data.get('opening', {}))
    for _, _, event in sorted(winners.values(), key=lambda winner: winner[1]):
        if event.get('void', False):
            continue

        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances[key] = balances.get(key, 0) + amount(event, data['rounding'])

    return {'balances': balances}

from decimal import Decimal
from fractions import Fraction


def _fraction(value):
    return Fraction(Decimal(str(value)))


def _round_nonnegative(value, mode):
    numerator, denominator = value.numerator, value.denominator
    quotient, remainder = divmod(numerator, denominator)

    if mode == 'half_up':
        return quotient + (2 * remainder >= denominator)
    if mode in ('half_even', 'nearest'):
        return quotient + (
            2 * remainder > denominator
            or (2 * remainder == denominator and quotient % 2 == 1)
        )
    if mode in ('ceil', 'ceiling'):
        return quotient + (remainder != 0)
    return quotient


def amount(event, mode):
    price = _fraction(event['price'])
    quantity = _fraction(event.get('quantity', 1))
    discount_bp = _fraction(event.get('discount_bp', 0))
    discount_bp = max(Fraction(0), min(Fraction(10000), discount_bp))

    discounted = price * quantity * (Fraction(10000) - discount_bp) / 10000
    net = _round_nonnegative(discounted, mode)

    tax_bp = _fraction(event.get('tax_bp', 0))
    tax = _round_nonnegative(Fraction(net) * tax_bp / 10000, mode)
    total = net + tax
    return -total if event.get('kind') == 'refund' else total
